begin;
insert into auth.users(id,email_confirmed_at) values('55555555-5555-4555-8555-555555555555',now());
set local role service_role;
do $$
declare owner uuid='11111111-1111-4111-8111-111111111111'; uid uuid='55555555-5555-4555-8555-555555555555'; a jsonb; original public.reporters; current_profile public.reporters; role_id uuid; target_id uuid; quoted_fee integer;
begin
 select id into role_id from public.membership_roles where name='رپورٹر';
 select id,fee into target_id,quoted_fee from public.membership_roles where name='بیورو چیف';
 a=public.create_membership_application(uid,'changes@example.test','{"name":"Role change member","father_name":"Father","cnic":"35202-5555555-5","phone":"03001234567","address":"Private","role":"رپورٹر","designation_area":"Lahore","province":"Punjab","district":"Lahore","tehsil":"","city":"Lahore"}',role_id,1);
 a=public.submit_membership_payment(uid,(a->>'version')::integer,a->>'id'||'/first.webp');
 a=public.review_membership_application((a->>'id')::uuid,owner,'owner@example.test',jsonb_build_object('decision','approve','version',a->'version'));
 select * into original from public.reporters where id=(a->>'reporter_id')::uuid;
 begin perform public.renew_membership_without_payment((a->>'id')::uuid,uid,'member@example.test',(a->>'version')::integer,'Waive'); raise exception 'Member granted free renewal'; exception when insufficient_privilege then null; end;
 begin perform public.renew_membership_without_payment((a->>'id')::uuid,owner,'owner@example.test',(a->>'version')::integer,''); raise exception 'Empty waiver reason'; exception when invalid_parameter_value then null; end;
 begin perform public.request_member_designation(uid,(a->>'version')::integer,role_id,1); raise exception 'Same role accepted'; exception when invalid_parameter_value then null; end;
 begin perform public.request_member_designation(uid,(a->>'version')::integer,target_id,999); raise exception 'Stale quote accepted'; exception when serialization_failure then null; end;
 a=public.request_member_designation(uid,(a->>'version')::integer,target_id,1);
 assert (a->'pending_designation'->>'fee')::integer=quoted_fee;
 assert (select to_jsonb(r)=to_jsonb(original) from public.reporters r where id=original.id), 'Quote cannot change public profile';
 begin perform public.renew_membership_without_payment((a->>'id')::uuid,owner,'owner@example.test',(a->>'version')::integer,'Waive'); raise exception 'Waiver bypassed change payment'; exception when serialization_failure then null; end;
 a=public.cancel_member_designation(uid,(a->>'version')::integer);
 assert a->>'pending_designation' is null;
 a=public.request_member_designation(uid,(a->>'version')::integer,target_id,1);
 a=public.submit_membership_payment(uid,(a->>'version')::integer,a->>'id'||'/change.webp');
 begin perform public.cancel_member_designation(uid,(a->>'version')::integer); raise exception 'Changed submitted proof'; exception when serialization_failure then null; end;
 a=public.review_membership_application((a->>'id')::uuid,owner,'owner@example.test',jsonb_build_object('decision','reject','version',a->'version','reason','Wrong receipt'));
 assert a->>'status'='approved' and a->>'renewal_status'='rejected';
 assert (select to_jsonb(r)=to_jsonb(original) from public.reporters r where id=original.id), 'Rejection cannot change active profile';
 a=public.submit_membership_payment(uid,(a->>'version')::integer,a->>'id'||'/corrected.webp');
 update public.membership_roles set fee=fee+1000,version=version+1 where id=target_id;
 a=public.review_membership_application((a->>'id')::uuid,owner,'owner@example.test',jsonb_build_object('decision','approve','version',a->'version'));
 select * into current_profile from public.reporters where id=original.id;
 assert current_profile.designation='بیورو چیف' and current_profile.city=original.city;
 assert current_profile.id=original.id and current_profile.card_number=original.card_number and current_profile.expiry_date=original.expiry_date and current_profile.issue_date=original.issue_date;
 assert current_profile.membership_expires_at=original.membership_expires_at+interval '30 days';
 assert (a->>'fee')::integer=quoted_fee and a->>'role_id'=target_id::text and a->>'pending_designation' is null;
 assert exists(select 1 from public.membership_reviews where application_id=(a->>'id')::uuid and fee=quoted_fee and source='payment' and request_snapshot->>'role'='بیورو چیف');
 a=public.renew_membership_without_payment((a->>'id')::uuid,owner,'owner@example.test',(a->>'version')::integer,'Owner waived this month');
 assert exists(select 1 from public.membership_reviews where application_id=(a->>'id')::uuid and fee=0 and source='waiver' and proof_path is null);
 assert (select membership_expires_at=original.membership_expires_at+interval '60 days' and city=original.city and expiry_date=original.expiry_date from public.reporters where id=original.id);
 begin perform public.renew_membership_without_payment((a->>'id')::uuid,owner,'owner@example.test',(a->>'version')::integer-1,'Retry'); raise exception 'Duplicate free renewal'; exception when serialization_failure then null; end;
 assert not has_function_privilege('authenticated','public.renew_membership_without_payment(uuid,uuid,text,integer,text)','EXECUTE');
 assert not has_function_privilege('authenticated','public.request_member_designation(uuid,integer,uuid,integer)','EXECUTE');
end $$;
rollback;
